public boolean shouldPrintMessage(int timestamp, String message) {
    // Check if the message map is null; if so, initialize it
    if (map == null) {
        map = new HashMap<>();
    }

    // Check if the message has already been printed in the given timestamp or within the last 10 seconds
    if (map.containsKey(message)) {
        if (timestamp - map.get(message) < 10) {
            return false;
        } else {
            // Update the timestamp for the message
            map.put(message, timestamp);
        }
    } else {
        // Add the message to the map with the current timestamp
        map.put(message, timestamp);
    }

    // The message can be printed
    return true;
}

