private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (vertices == null || vertices.isEmpty()) {
        return true; // An empty graph or empty subset of vertices is considered a clique by definition.
    }

    Iterator<V> iterator = vertices.iterator();
    V vertex = iterator.next();
    Set<E> edges = graph.edgesOf(vertex);

    while (iterator.hasNext()) {
        V otherVertex = iterator.next();
        if (!edges.contains(graph.getEdge(vertex, otherVertex))) {
            return false; // If any edge is missing, the subgraph is not a clique.
        }
    }

    return true;
}

