                    pathSegments.add(segment);
                }
            }
        }
    } catch (IllegalArgumentException e) {
        // Handle invalid URI or other IllegalArgumentExceptions
        throw new RuntimeException("Invalid URI", e);
    }
    return pathSegments;
}

