public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relative path must not be null");
    }

    // Split the path into its components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Remove any trailing slash in the path
    if (path.endsWith("/")) {
        pathComponents = Arrays.copyOf(pathComponents, pathComponents.length - 1);
    }

    // Process the relative path components
    for (String component : relativePathComponents) {
        if ("..".equals(component)) {
            // Move up one directory
            if (pathComponents.length > 0) {
                pathComponents = Arrays.copyOf(pathComponents, pathComponents.length - 1);
            }
        } else if (!"".equals(component)) {
            // Append the component to the path
            pathComponents = Arrays.copyOf(pathComponents, pathComponents.length + 1);
            pathComponents[pathComponents.length - 1] = component;
        }
    }

    // Join the components back into a file path
    return String.join("/", pathComponents);
}

