static long compressTimeBucket(long timeBucket, int dayStep) {
    // Extract the year, month, and day from the time bucket
    int year = (int) (timeBucket / 10000000000L);
    int month = (int) ((timeBucket / 100000000) % 100);
    int day = (int) ((timeBucket / 1000000) % 100);

    // Calculate the new day based on the dayStep
    day -= day % dayStep;

    // Validate the day to ensure it stays within the valid range of a month
    if (day < 1) {
        month--;
        if (month < 1) {
            year--;
            month = 12;
        }
        Calendar calendar = Calendar.getInstance();
        calendar.set(year, month - 1, 1);
        int lastDayOfMonth = calendar.getActualMaximum(Calendar.DAY_OF_MONTH);
        day = lastDayOfMonth + day;
    }

    // Reconstruct the time bucket with the new day
    long compressedTimeBucket = (year * 10000000000L) + (month * 100000000) + (day * 1000000);

    return compressedTimeBucket;
}

