public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || index >= str.length()) {
        throw new StringIndexOutOfBoundsException("Index out of bounds: " + index);
    }
    if (len < 0 || index + len > str.length()) {
        throw new StringIndexOutOfBoundsException("Length out of bounds: " + len);
    }

    int size = 0;
    int end = index + len;
    for (int i = index; i < end; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size++;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if ((c >> 5) == 6) {
            size += 3;
        } else if ((c >> 4) == 14) {
            size += 4;
        } else {
            throw new IllegalArgumentException("Invalid UTF-16 character at index: " + i);
        }
    }
    return size;
}

