public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null || session == null || lb == null) {
        throw new IllegalArgumentException("Inputs cannot be null");
    }

    try {
        byte[] bytes = str.toString().getBytes("UTF-8");
        if (bytes.length > lb.getRemaining()) {
            lb = session.openNestedBuffer(lb, bytes.length);
        }
        lb.write(bytes);
        return lb;
    } catch (Exception e) {
        throw new RuntimeException("Error writing UTF-8 bytes", e);
    }
}

