public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;

    // Assuming LinkedBuffer has a method getContent() to get the buffer content as a byte array
    byte[] content = node.getContent();
    if (content != null) {
        out.write(content);
        totalSize = content.length;
    }

    // Assuming LinkedBuffer has a method getNext() to get the next buffer in the chain
    LinkedBuffer next = node.getNext();
    while (next != null) {
        out.write(next.getContent());
        totalSize += next.getContent().length;
        next = next.getNext();
    }

    return totalSize;
}

